-- Missing original schema, reconstructed for clean installations only.
create schema if not exists private;
grant usage on schema private to authenticated;
create type public.admin_role as enum ('global_admin','store_manager','staff');
create table public.stores(id bigint generated by default as identity primary key,name text not null,address text not null default '',phone text not null default '',active boolean not null default true,preparation_minutes integer not null default 10,accepting_pickup boolean not null default true,image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id bigint generated by default as identity primary key,name text not null,image_url text,active boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now());
create table public.products(id bigint generated by default as identity primary key,category_id bigint references public.categories(id) on delete set null,name text not null,description text not null default '',price_cents integer not null check(price_cents>=0),image_url text,badge text,available boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.staff(user_id uuid primary key references auth.users(id) on delete cascade,role public.admin_role not null default 'staff',store_id bigint references public.stores(id) on delete restrict,display_name text not null default '',email text,active boolean not null default true,created_at timestamptz not null default now(),check(role='global_admin' or store_id is not null));
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade);
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.shop_settings(id boolean primary key default true check(id),shop_name text not null default 'Coffee Shop',accepting_pickup boolean not null default true,preparation_minutes integer not null default 10,logo_url text,updated_at timestamptz not null default now());
create table public.campaigns(id bigint generated by default as identity primary key,title text not null,body text not null default '',image_url text,active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.store_product_availability(store_id bigint references public.stores(id) on delete cascade,product_id bigint references public.products(id) on delete cascade,available boolean not null default true,updated_at timestamptz not null default now(),primary key(store_id,product_id));
create table public.orders(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete set null,store_id bigint references public.stores(id) on delete restrict,order_number text,customer_name text not null,total_cents integer not null check(total_cents>=0),status text not null default 'new' check(status in ('new','preparing','ready','completed','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id bigint generated by default as identity primary key,order_id bigint not null references public.orders(id) on delete cascade,product_id bigint references public.products(id) on delete set null,product_name text not null,unit_price_cents integer not null check(unit_price_cents>=0),quantity integer not null check(quantity between 1 and 20),customization jsonb not null default '{}');
create function private.current_staff_role() returns public.admin_role language sql stable security definer set search_path='' as $$select role from public.staff where user_id=auth.uid() and active$$;
revoke all on function private.current_staff_role() from public,anon;
grant execute on function private.current_staff_role() to authenticated;
create function private.can_manage_store(p_store bigint) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.staff where user_id=auth.uid() and active and (role='global_admin' or store_id=p_store))$$;
revoke all on function private.can_manage_store(bigint) from public,anon;
grant execute on function private.can_manage_store(bigint) to authenticated;
do $$declare t text;begin foreach t in array array['stores','categories','products','shop_settings','campaigns','store_product_availability'] loop
execute format('alter table public.%I enable row level security',t);
execute format('create policy catalog_read on public.%I for select to anon,authenticated using(true)',t);
execute format('create policy catalog_admin_write on public.%I for all to authenticated using(private.current_staff_role()=''global_admin'') with check(private.current_staff_role()=''global_admin'')',t);
end loop;end$$;
alter table public.staff enable row level security;
create policy staff_read on public.staff for select to authenticated using(user_id=auth.uid() or private.current_staff_role()='global_admin');
create policy staff_admin on public.staff for all to authenticated using(private.current_staff_role()='global_admin') with check(private.current_staff_role()='global_admin');
alter table public.admin_users enable row level security;
create policy admin_self_read on public.admin_users for select to authenticated using(user_id=auth.uid());
alter table public.profiles enable row level security;
create policy users_read_own_profile on public.profiles for select to authenticated using(user_id=auth.uid() or private.current_staff_role()='global_admin');
create policy users_insert_own_profile on public.profiles for insert to authenticated with check(user_id=auth.uid());
create policy users_update_own_profile on public.profiles for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.orders enable row level security;
create policy users_and_staff_read_orders on public.orders for select to authenticated using(user_id=auth.uid() or private.can_manage_store(store_id));
create policy users_create_own_orders on public.orders for insert to authenticated with check(user_id=auth.uid());
create policy staff_update_orders on public.orders for update to authenticated using(private.can_manage_store(store_id)) with check(private.can_manage_store(store_id));
alter table public.order_items enable row level security;
create policy users_and_staff_read_order_items on public.order_items for select to authenticated using(exists(select 1 from public.orders where id=order_id));
create policy users_create_own_order_items on public.order_items for insert to authenticated with check(exists(select 1 from public.orders where id=order_id and user_id=auth.uid()));
grant usage on schema public to anon,authenticated;
grant select on all tables in schema public to anon,authenticated;
grant insert,update,delete on all tables in schema public to authenticated;
grant usage,select on all sequences in schema public to authenticated;
alter default privileges in schema public grant select,insert,update,delete on tables to authenticated;
alter default privileges in schema public grant select on tables to anon;
alter default privileges in schema public grant usage,select on sequences to authenticated;
alter publication supabase_realtime add table public.orders,public.order_items,public.stores,public.products,public.campaigns,public.shop_settings;
